    87    /*                                                                       */
    88    /* The macro ALL_POINTS is used in `ft_var_readpackedpoints'.  It        */
    89    /* indicates that there is a delta for every point without needing to    */
    90    /* enumerate all of them.                                                */
    91    /*                                                                       */
    92
    93    /* ensure that value `0' has the same width as a pointer */
    94  #define ALL_POINTS  (FT_UShort*)~(FT_PtrDist)0
    95
    96
    97  #define GX_PT_POINTS_ARE_WORDS      0x80U
    98  #define GX_PT_POINT_RUN_COUNT_MASK  0x7FU
    99
