   101    /*************************************************************************/
   102    /*                                                                       */
   103    /* <Function>                                                            */
   104    /*    ft_var_readpackedpoints                                            */
   105    /*                                                                       */
   106    /* <Description>                                                         */
   107    /*    Read a set of points to which the following deltas will apply.     */
   108    /*    Points are packed with a run length encoding.                      */
   109    /*                                                                       */
   110    /* <Input>                                                               */
   111    /*    stream    :: The data stream.                                      */
   112    /*                                                                       */
   113    /*    size      :: The size of the table holding the data.               */
   114    /*                                                                       */
   115    /* <Output>                                                              */
   116    /*    point_cnt :: The number of points read.  A zero value means that   */
   117    /*                 all points in the glyph will be affected, without     */
   118    /*                 enumerating them individually.                        */
   119    /*                                                                       */
   120    /* <Return>                                                              */
   121    /*    An array of FT_UShort containing the affected points or the        */
   122    /*    special value ALL_POINTS.                                          */
   123    /*                                                                       */
   124    static FT_UShort*
   125    ft_var_readpackedpoints( FT_Stream  stream,
   126                             FT_ULong   size,
   127                             FT_UInt   *point_cnt )
   128    {
   129      FT_UShort *points = NULL;
   130      FT_UInt    n;
   131      FT_UInt    runcnt;
   132      FT_UInt    i, j;
   133      FT_UShort  first;
   134      FT_Memory  memory = stream->memory;
   135      FT_Error   error  = FT_Err_Ok;
   136
   137      FT_UNUSED( error );
   138
   139
   140      *point_cnt = 0;
   141
   142      n = FT_GET_BYTE();
   143      if ( n == 0 )
   144        return ALL_POINTS;
   145
   146      if ( n & GX_PT_POINTS_ARE_WORDS )
   147      {
   148        n  &= GX_PT_POINT_RUN_COUNT_MASK;
   149        n <<= 8;
   150        n  |= FT_GET_BYTE();
   151      }
   152
   153      if ( n > size )
   154      {
   155        FT_TRACE1(( "ft_var_readpackedpoints: number of points too large\n" ));
   156        return NULL;
   157      }
   158
   159      /* in the nested loops below we increase `i' twice; */
   160      /* it is faster to simply allocate one more slot    */
   161      /* than to add another test within the loop         */
   162      if ( FT_NEW_ARRAY( points, n + 1 ) )
   163        return NULL;
   164
   165      *point_cnt = n;
   166
   167      first = 0;
   168      i     = 0;
   169      while ( i < n )
   170      {
   171        runcnt = FT_GET_BYTE();
   172        if ( runcnt & GX_PT_POINTS_ARE_WORDS )
   173        {
   174          runcnt     &= GX_PT_POINT_RUN_COUNT_MASK;
   175          first      += FT_GET_USHORT();
   176          points[i++] = first;
   177
   178          /* first point not included in run count */
   179          for ( j = 0; j < runcnt; j++ )
   180          {
   181            first      += FT_GET_USHORT();
   182            points[i++] = first;
   183            if ( i >= n )
   184              break;
   185          }
   186        }
   187        else
   188        {
   189          first      += FT_GET_BYTE();
   190          points[i++] = first;
   191
   192          for ( j = 0; j < runcnt; j++ )
   193          {
   194            first      += FT_GET_BYTE();
   195            points[i++] = first;
   196            if ( i >= n )
   197              break;
   198          }
   199        }
   200      }
   201
   202      return points;
   203    }
