   206  #define GX_DT_DELTAS_ARE_ZERO       0x80U
   207  #define GX_DT_DELTAS_ARE_WORDS      0x40U
   208  #define GX_DT_DELTA_RUN_COUNT_MASK  0x3FU
   209
   210
  3100                            end_point,
  3101                            cur_delta,
  3102                            in_points,
  3103                            out_points );
  3104          else
  3105          {
  3106            /* otherwise handle remaining points       */
  3107            /* at the end and beginning of the contour */
  3108            tt_delta_interpolate( cur_delta + 1,
  3109                                  end_point,
  3110                                  cur_delta,
  3111                                  first_delta,
  3112                                  in_points,
  3113                                  out_points );
  3114
  3115            if ( first_delta > 0 )
  3116              tt_delta_interpolate( first_point,
  3117                                    first_delta - 1,
  3118                                    cur_delta,
  3119                                    first_delta,
  3120                                    in_points,
  3121                                    out_points );
  3122          }
  3123        }
  3124        contour++;
  3125
  3126      } while ( contour < outline->n_contours );
  3127    }
