  3130    /*************************************************************************/
  3131    /*                                                                       */
  3132    /* <Function>                                                            */
  3133    /*    TT_Vary_Apply_Glyph_Deltas                                         */
  3134    /*                                                                       */
  3135    /* <Description>                                                         */
  3136    /*    Apply the appropriate deltas to the current glyph.                 */
  3137    /*                                                                       */
  3138    /* <Input>                                                               */
  3139    /*    face        :: A handle to the target face object.                 */
  3140    /*                                                                       */
  3141    /*    glyph_index :: The index of the glyph being modified.              */
  3142    /*                                                                       */
  3143    /*    n_points    :: The number of the points in the glyph, including    */
  3144    /*                   phantom points.                                     */
  3145    /*                                                                       */
  3146    /* <InOut>                                                               */
  3147    /*    outline     :: The outline to change.                              */
  3148    /*                                                                       */
  3149    /* <Return>                                                              */
  3150    /*    FreeType error code.  0 means success.                             */
  3151    /*                                                                       */
  3152    FT_LOCAL_DEF( FT_Error )
  3153    TT_Vary_Apply_Glyph_Deltas( TT_Face      face,
  3154                                FT_UInt      glyph_index,
  3155                                FT_Outline*  outline,
  3156                                FT_UInt      n_points )
  3157    {
  3158      FT_Stream   stream = face->root.stream;
  3159      FT_Memory   memory = stream->memory;
  3160      GX_Blend    blend  = face->blend;
  3161
  3162      FT_Vector*  points_org = NULL;
  3163      FT_Vector*  points_out = NULL;
  3164      FT_Bool*    has_delta  = NULL;
  3165
  3166      FT_Error    error;
  3167      FT_ULong    glyph_start;
  3168      FT_UInt     tupleCount;
  3169      FT_ULong    offsetToData;
  3170      FT_ULong    here;
  3171      FT_UInt     i, j;
  3172      FT_Fixed*   tuple_coords    = NULL;
  3173      FT_Fixed*   im_start_coords = NULL;
  3174      FT_Fixed*   im_end_coords   = NULL;
  3175      FT_UInt     point_count, spoint_count = 0;
  3176      FT_UShort*  sharedpoints = NULL;
  3177      FT_UShort*  localpoints  = NULL;
  3178      FT_UShort*  points;
  3179      FT_Short    *deltas_x, *deltas_y;
  3180
  3181
  3182      if ( !face->doblend || !blend )
  3183        return FT_THROW( Invalid_Argument );
  3184
  3185      if ( glyph_index >= blend->gv_glyphcnt      ||
  3186           blend->glyphoffsets[glyph_index] ==
  3187             blend->glyphoffsets[glyph_index + 1] )
  3188      {
  3189        FT_TRACE2(( "TT_Vary_Apply_Glyph_Deltas:"
  3190                    " no variation data for this glyph\n" ));
  3191        return FT_Err_Ok;
  3192      }
  3193
  3194      if ( FT_NEW_ARRAY( points_org, n_points ) ||
  3195           FT_NEW_ARRAY( points_out, n_points ) ||
  3196           FT_NEW_ARRAY( has_delta, n_points )  )
  3197        goto Fail1;
  3198
  3199      if ( FT_STREAM_SEEK( blend->glyphoffsets[glyph_index] )   ||
  3200           FT_FRAME_ENTER( blend->glyphoffsets[glyph_index + 1] -
  3201                             blend->glyphoffsets[glyph_index] ) )
  3202        goto Fail1;
  3203
  3204      glyph_start = FT_Stream_FTell( stream );
  3205
  3206      /* each set of glyph variation data is formatted similarly to `cvar' */
  3207      /* (except we get shared points and global tuples)                   */
  3208
  3209      if ( FT_NEW_ARRAY( tuple_coords, blend->num_axis )    ||
  3210           FT_NEW_ARRAY( im_start_coords, blend->num_axis ) ||
  3211           FT_NEW_ARRAY( im_end_coords, blend->num_axis )   )
  3212        goto Fail2;
  3213
  3214      tupleCount   = FT_GET_USHORT();
  3215      offsetToData = FT_GET_USHORT();
  3216
  3217      /* rough sanity test */
  3218      if ( offsetToData + ( tupleCount & GX_TC_TUPLE_COUNT_MASK ) * 4 >
  3219             blend->gvar_size )
  3220      {
  3221        FT_TRACE2(( "TT_Vary_Apply_Glyph_Deltas:"
  3222                    " invalid glyph variation array header\n" ));
  3223
  3224        error = FT_THROW( Invalid_Table );
  3225        goto Fail2;
  3226      }
  3227
  3228      offsetToData += glyph_start;
  3229
  3230      if ( tupleCount & GX_TC_TUPLES_SHARE_POINT_NUMBERS )
  3231      {
  3232        here = FT_Stream_FTell( stream );
  3233
  3234        FT_Stream_SeekSet( stream, offsetToData );
  3235
  3236        sharedpoints = ft_var_readpackedpoints( stream,
  3237                                                blend->gvar_size,
  3238                                                &spoint_count );
  3239        offsetToData = FT_Stream_FTell( stream );
  3240
  3241        FT_Stream_SeekSet( stream, here );
  3242      }
  3243
  3244      FT_TRACE5(( "gvar: there are %d tuples:\n",
  3245                  tupleCount & GX_TC_TUPLE_COUNT_MASK ));
  3246
  3247      for ( j = 0; j < n_points; j++ )
  3248        points_org[j] = outline->points[j];
  3249
  3250      for ( i = 0; i < ( tupleCount & GX_TC_TUPLE_COUNT_MASK ); i++ )
  3251      {
  3252        FT_UInt   tupleDataSize;
  3253        FT_UInt   tupleIndex;
  3254        FT_Fixed  apply;
  3255
  3256
  3257        FT_TRACE6(( "  tuple %d:\n", i ));
  3258
  3259        tupleDataSize = FT_GET_USHORT();
  3260        tupleIndex    = FT_GET_USHORT();
  3261
  3262        if ( tupleIndex & GX_TI_EMBEDDED_TUPLE_COORD )
  3263        {
  3264          for ( j = 0; j < blend->num_axis; j++ )
  3265            tuple_coords[j] = FT_GET_SHORT() * 4;   /* convert from        */
  3266                                                    /* short frac to fixed */
  3267        }
  3268        else if ( ( tupleIndex & GX_TI_TUPLE_INDEX_MASK ) >= blend->tuplecount )
  3269        {
  3270          FT_TRACE2(( "TT_Vary_Apply_Glyph_Deltas:"
  3271                      " invalid tuple index\n" ));
  3272
  3273          error = FT_THROW( Invalid_Table );
  3274          goto Fail2;
  3275        }
  3276        else
  3277          FT_MEM_COPY(
  3278            tuple_coords,
  3279            &blend->tuplecoords[( tupleIndex & 0xFFF ) * blend->num_axis],
  3280            blend->num_axis * sizeof ( FT_Fixed ) );
  3281
  3282        if ( tupleIndex & GX_TI_INTERMEDIATE_TUPLE )
  3283        {
  3284          for ( j = 0; j < blend->num_axis; j++ )
  3285            im_start_coords[j] = FT_GET_SHORT() * 4;
  3286          for ( j = 0; j < blend->num_axis; j++ )
  3287            im_end_coords[j] = FT_GET_SHORT() * 4;
  3288        }
  3289
  3290        apply = ft_var_apply_tuple( blend,
  3291                                    (FT_UShort)tupleIndex,
  3292                                    tuple_coords,
  3293                                    im_start_coords,
  3294                                    im_end_coords );
  3295
  3296        if ( apply == 0 )              /* tuple isn't active for our blend */
  3297        {
  3298          offsetToData += tupleDataSize;
  3299          continue;
  3300        }
  3301
  3302        here = FT_Stream_FTell( stream );
  3303
  3304        FT_Stream_SeekSet( stream, offsetToData );
  3305
  3306        if ( tupleIndex & GX_TI_PRIVATE_POINT_NUMBERS )
  3307        {
  3308          localpoints = ft_var_readpackedpoints( stream,
  3309                                                 blend->gvar_size,
  3310                                                 &point_count );
